"""Extract file-system ops (write/edit/bash-destructive) from opencode.db.

Produces /tmp/opencode/ops.jsonl — one JSON op per line, in strict
chronological order across all sessions of the three repos:
  {t: 'W'|'E'|'D'|'M', path, content|old|new|src|dst, status}
"""

import json
import re
import sqlite3
import sys

DB = "/home/jorj/.local/share/opencode/opencode.db"
REPOS = (
    "/home/jorj/Загрузки/Improve-ImgSLI",
    "/home/jorj/Загрузки/sli-ui-toolkit",
    "/home/jorj/Загрузки/improve-imgsli-internal-docs",
)
OUT = "/tmp/opencode/ops.jsonl"

RM_RE = re.compile(r"\b(?:git\s+)?rm\s+(?:-[a-zA-Z]+\s+)*(.+)$")
MV_RE = re.compile(r"\b(?:git\s+)?mv\s+(?:-[a-zA-Z]+\s+)?(\S+)\s+(\S+)$")
DANGEROUS_RE = re.compile(r"\bgit\s+(?:reset\s+--hard|checkout\s+--\s+\.|clean\s+-(?:f|d|fd)+)\b")


def in_repo(path: str) -> bool:
    if not path:
        return False
    p = path.rstrip("/")
    for repo in REPOS:
        if p == repo or p.startswith(repo + "/"):
            return True
    return False


def split_args(s: str) -> list[str]:
    """Split a shell command fragment on whitespace, stripping quotes."""
    out = []
    for tok in re.findall(r"'[^']*'|\"[^\"]*\"|\S+", s):
        out.append(tok.strip("\"'"))
    return out


def parse_bash(command: str, cwd: str, ops: list[dict]) -> None:
    if not in_repo(cwd):
        return
    # skip compound/conditional commands we cannot trust
    if re.search(r"\b(if|then|else|fi|for|while|&&|\|\|)\b", command) and re.search(
        r"\brm\b|\bmv\b", command
    ):
        return
    m = RM_RE.search(command)
    if m:
        for tok in split_args(m.group(1)):
            path = tok if tok.startswith("/") else f"{cwd}/{tok}"
            if in_repo(path) and ".." not in path.split("/"):
                ops.append({"t": "D", "path": path, "status": "completed"})
        return
    m = MV_RE.search(command)
    if m:
        src, dst = m.group(1), m.group(2)
        src = src if src.startswith("/") else f"{cwd}/{src}"
        dst = dst if dst.startswith("/") else f"{cwd}/{dst}"
        if in_repo(src) and in_repo(dst):
            ops.append({"t": "M", "src": src, "dst": dst, "status": "completed"})
        return
    if DANGEROUS_RE.search(command):
        ops.append({"t": "DANGEROUS", "command": command, "status": "completed"})


def main() -> None:
    con = sqlite3.connect(DB)
    cur = con.cursor()
    sessions = cur.execute(
        "SELECT id, time_created, directory FROM session ORDER BY time_created"
    ).fetchall()

    ops: list[tuple[int, int, int, dict]] = []
    for sid, stime, directory in sessions:
        if not directory or not any(directory.startswith(r) for r in REPOS):
            continue
        parts = cur.execute(
            "SELECT time_created, data FROM part WHERE session_id=? ORDER BY time_created",
            (sid,),
        ).fetchall()
        for idx, (ptime, data) in enumerate(parts):
            try:
                j = json.loads(data)
            except Exception:
                continue
            if j.get("type") != "tool":
                continue
            state = j.get("state", {})
            tool = j.get("tool")
            status = state.get("status", "completed")
            inp = state.get("input", {})
            if tool == "write" and isinstance(inp.get("filePath"), str):
                ops.append(
                    (stime, ptime, idx,
                     {"t": "W", "path": inp["filePath"], "content": inp.get("content", ""),
                      "status": status})
                )
            elif tool == "edit" and isinstance(inp.get("filePath"), str):
                ops.append(
                    (stime, ptime, idx,
                     {"t": "E", "path": inp["filePath"], "old": inp.get("oldString", ""),
                      "new": inp.get("newString", ""), "status": status})
                )
            elif tool == "bash" and isinstance(inp.get("command"), str):
                parse_bash(inp["command"], directory, [])
                # parse into ops with ordering info
                tmp: list[dict] = []
                parse_bash(inp["command"], directory, tmp)
                for op in tmp:
                    ops.append((stime, ptime, idx, op))

    ops.sort(key=lambda x: (x[0], x[1], x[2]))
    with open(OUT, "w", encoding="utf-8") as f:
        for _, _, _, op in ops:
            f.write(json.dumps(op, ensure_ascii=False) + "\n")
    kinds: dict[str, int] = {}
    for _, _, _, op in ops:
        kinds[op["t"]] = kinds.get(op["t"], 0) + 1
    print(f"total ops: {len(ops)} | kinds: {kinds}")
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()

