                 tracer.record(
                     f"input.{_label}",
                     f"{_label} {_event_summary(event)}",
                     {"event": _event_summary(event), "span_id": span_id},
                     caller_skip=1,
                 )
                 tracer._push_depth()
                 try:
                     return _orig(self, event)
                 finally:
                     tracer._pop_depth()
             finally:
                 tracer.record(
                     f"input.{_label}.end",
                     f"{_label} done",
                     {
                         "span_id": span_id,
                         "duration_ms": (time.monotonic() - t0) * 1000.0,
                     },
                     caller_skip=1,
                 )
                 tracer.end_trace()
         setattr(widget_cls, method_name, traced)

     for widget_cls in widget_classes:
         for method, label in [
             ("mousePressEvent", "mpress"),
             ("mouseReleaseEvent", "mrel"),
             ("mouseMoveEvent", "mmove"),
             ("wheelEvent", "wheel"),
             ("keyPressEvent", "kpress"),
             ("keyReleaseEvent", "krel"),
         ]:
             wrap(widget_cls, method, label)

 def _event_summary(event) -> str:
     parts = []
     try:
         pos = event.position()
         parts.append(f"pos=({pos.x():.0f},{pos.y():.0f})")
     except Exception:
         pass
     try:
         btn = event.button()
         if btn is not None:
             parts.append(f"btn={int(btn)}")
     except Exception:
         pass
     try:
         btns = event.buttons()
         if btns is not None:
             parts.append(f"btns={int(btns)}")
     except Exception:
         pass
     try:
         mods = event.modifiers()
         if mods is not None:
             parts.append(f"mods={int(mods)}")
     except Exception:
         pass
     try:
         key = event.key()
         parts.append(f"key={key}")
     except Exception:
         pass
     try:
         delta = event.angleDelta()
         parts.append(f"dy={delta.y()}")
     except Exception:
         pass
     return " ".join(parts) if parts else type(event).__name__

