 class Tracer:
     _instance: "Tracer | None" = None

     def __init__(self, ring_size: int = _DEFAULT_RING_SIZE):
         self._lock = threading.Lock()
         self._buffer: deque[TraceRecord] = deque(maxlen=ring_size)
         self._seq = 0
