         skip = os.environ.get("IMGSLI_TRACE_SKIP", "").strip()
         if allow:
             self._allow_kinds = tuple(p.strip() for p in allow.split(",") if p.strip())
         if skip:
             self._skip_kinds = tuple(p.strip() for p in skip.split(",") if p.strip())
