     pil_image: Image.Image, copy: bool = False
 ) -> Optional[QPixmap]:
     qimage = pil_to_qimage_zero_copy(pil_image)
     if qimage is None or qimage.isNull():
         return None

     pixmap = QPixmap.fromImage(qimage)

