--- src/shared/rendering/shaders/glass_panel/glass_panel_pass.vert	
+++ src/shared/rendering/shaders/glass_panel/glass_panel_pass.vert	
@@ -0,0 +1,15 @@
+#version 440
+
+// Shared fullscreen-triangle vertex shader for the glass-panel blur/composite
+// passes (glass_blur.frag, glass_composite.frag) -- both passes render into a
+// scratch texture sized exactly to one panel, so no per-vertex uniform data
+// (position, UV) is needed beyond the "big triangle" trick.
+
+layout(location = 0) out vec2 vUv;
+
+void main()
+{
+    vec2 pos = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
+    vUv = pos;
+    gl_Position = vec4(pos * 2.0 - 1.0, 0.0, 1.0);
+}

Index: src/shared/rendering/shaders/glass_panel/glass_text_downsample.frag
===================================================================
--- src/shared/rendering/shaders/glass_panel/glass_text_downsample.frag	
+++ src/shared/rendering/shaders/glass_panel/glass_text_downsample.frag	
@@ -0,0 +1,75 @@
+#version 440
+
+// Downsamples text_mask_tex (rasterized at SCALE x this panel's own device
+// resolution, see ui/widgets/glass_hud/text_mask.py's _TEXT_MASK_SUPERSAMPLE) down to
+// device resolution using a properly-scaled Lanczos-2 kernel, in one shader
+// pass -- replaces an earlier version of this pipeline that used GPU
+// hardware mip generation (QRhi's generateMips(), a plain box filter per
+// level) for this same downscale: box-filtered mips are visibly softer than
+// Lanczos on the sharp alpha edges a rasterized glyph mask is made of (a
+// 2-level box chain approximates a triangle/bilinear filter in the
+// frequency domain, not a windowed sinc) -- reported live as "looks
+// trilinear, not Lanczos" despite textureLod() landing on the exact right
+// mip level. See docs/dev/rendering/glass-panel-text-vibrancy-plan.md's bug
+// 17 for the full before/after.
+//
+// SCALE must match ui.widgets.glass_hud._TEXT_MASK_SUPERSAMPLE /
+// shared.rendering.glass_panel._TEXT_MASK_SUPERSAMPLE (kept in sync by
+// comment on all three, same convention as those constants themselves).
+const float SCALE = 4.0;
+// Lanczos-2's own support radius is 2 source samples per destination sample
+// at 1:1; downsampling by SCALE widens that support proportionally (a
+// correctly *scaled* reconstruction filter, not the unscaled kernel
+// evaluated directly against source texels -- the latter would just alias)
+// -- see this pass's own docstring above. int(2.0 * SCALE) here, spelled as
+// a literal since GLSL doesn't allow a non-const-expression array/loop
+// bound derived from a `const float`.
+const int RADIUS = 8;
+
+layout(binding = 0) uniform sampler2D srcTex;
+
+layout(location = 0) in vec2 vUv;
+layout(location = 0) out vec4 fragColor;
+
+float sinc(float x)
+{
+    if (abs(x) < 1e-5)
+        return 1.0;
+    float px = 3.14159265358979 * x;
+    return sin(px) / px;
+}
+
+float lanczos2(float x)
+{
+    if (abs(x) >= 2.0)
+        return 0.0;
+    return sinc(x) * sinc(x * 0.5);
+}
+
+void main()
+{
+    vec2 srcSize = vec2(textureSize(srcTex, 0));
+    vec2 srcTexel = 1.0 / srcSize;
+    // Continuous source-space position (texel-index units) that this
+    // destination pixel's center maps back to.
+    vec2 centerPx = vUv * srcSize;
+    vec2 baseTexel = floor(centerPx);
+
+    vec4 sum = vec4(0.0);
+    float weightSum = 0.0;
+    for (int iy = -RADIUS; iy < RADIUS; iy++)
+    {
+        for (int ix = -RADIUS; ix < RADIUS; ix++)
+        {
+            vec2 sampleTexel = baseTexel + vec2(float(ix), float(iy)) + 0.5;
+            vec2 dist = (sampleTexel - centerPx) / SCALE;
+            float w = lanczos2(dist.x) * lanczos2(dist.y);
+            if (w == 0.0)
+                continue;
+            vec2 uv = sampleTexel * srcTexel;
+            sum += textureLod(srcTex, uv, 0.0) * w;
+            weightSum += w;
+        }
+    }
+    fragColor = sum / max(weightSum, 1e-5);
+}

Index: src/shared/rendering/shaders/mip_downsample.frag
===================================================================
--- src/shared/rendering/shaders/mip_downsample.frag	
+++ src/shared/rendering/shaders/mip_downsample.frag	
@@ -0,0 +1,32 @@
+#version 440
+
+// Generates one mip level of one layer of the shared tile texture array
+// (docs/dev/rendering/tile-array-atlas-plan.md Phase 9). Replaces
+// QRhiResourceUpdateBatch.generateMips, which regenerates every layer of the
+// array in one call -- O(array capacity) GPU work per dirtied tile instead
+// of O(1). One draw of this shader (a single fullscreen-quad pass targeting
+// exactly this (layer, level) via QRhiColorAttachment.setLayer/setLevel)
+// produces one destination level from the previous level;
+// MipCascadeGenerator cascades this call from level 1 up to the full chain
+// for a dirty layer. A single bilinear tap of the source level at the same
+// UV is a standard box-downsample for an exact 2x size step (what
+// glGenerateMipmap itself does per level), so no manual 2x2 averaging is
+// needed.
+
+layout(std140, binding = 0) uniform UBuf
+{
+    int layer;
+    int srcLevel;
+    int _pad0;
+    int _pad1;
+};
+
+layout(binding = 1) uniform sampler2DArray tileArray;
+
+layout(location = 0) in vec2 vTexCoord;
+layout(location = 0) out vec4 fragColor;
+
+void main()
+{
+    fragColor = textureLod(tileArray, vec3(vTexCoord, float(layer)), float(srcLevel));
+}

Index: src/shared/rendering/shaders/mip_downsample.vert
===================================================================
--- src/shared/rendering/shaders/mip_downsample.vert	
+++ src/shared/rendering/shaders/mip_downsample.vert	
@@ -0,0 +1,28 @@
+#version 440
+
+// Fullscreen-quad vertex shader for mip_downsample.frag (docs/dev/rendering/
+// tile-array-atlas-plan.md Phase 9). corrMatrix here is NOT
+// rhi.clipSpaceCorrMatrix() (that's identity for a visible QRhiWidget's own
+// backend/context -- its later on-screen compositing absorbs the Y
+// convention) -- it's an unconditional Y-flip, set once from the CPU side
+// (MipCascadeGenerator._ensure_downsample_corr_buffer). This scratch render
+// target is never composited to screen, so nothing else cancels that flip
+// out; skipping it left each generated mip level's orientation alternating
+// by level parity relative to level 0 (each level samples the previous
+// level, which was itself already flipped once by this same pass).
+
+layout(std140, binding = 2) uniform VertUBuf
+{
+    mat4 corrMatrix;
+};
+
+layout(location = 0) in vec2 position;
+layout(location = 1) in vec2 texCoord;
+
+layout(location = 0) out vec2 vTexCoord;
+
+void main()
+{
+    gl_Position = corrMatrix * vec4(position, 0.0, 1.0);
+    vTexCoord = texCoord;
+}

