 def _overlay_enabled(store) -> bool:
     try:
         return bool(store.viewport.view_state.overlay_enabled)
     except AttributeError:
         return False


 def _space_pressed(store) -> bool:
     try:
         return bool(store.viewport.interaction_state.space_bar_pressed)
     except AttributeError:
         return False


