     def set_active_magnifier_visibility_parts(
         self,
         *,
         left: bool | None = None,
         center: bool | None = None,
         right: bool | None = None,
     ):
         model = self.ensure_active_magnifier()
         if model is None:
             return None
         updates = {}
         if left is not None:
             updates["visible_left"] = bool(left)
         if center is not None:
             updates["visible_center"] = bool(center)
         if right is not None:
             updates["visible_right"] = bool(right)
         if not updates:
             return model
         return update_magnifier_model(
             self._view,
             self._render,
             model.id,
             **updates,
         )

     def set_active_magnifier_freeze(
         self,
         freeze: bool,
         *,
         frozen_position: Point | None = None,
         new_offset: Point | None = None,
     ):
         model = self.ensure_active_magnifier()
         if model is None:
             return None
         updates = {
             "freeze": bool(freeze),
             "frozen_position": frozen_position if freeze else None,
         }
         if new_offset is not None:
             updates["offset_relative"] = new_offset
         return update_magnifier_model(
             self._view,
             self._render,
             model.id,
             **updates,
         )

     def set_all_magnifiers_freeze(
         self,
         freeze: bool,
         *,
         frozen_positions: dict[str, Point] | None = None,
         new_offsets: dict[str, Point | None] | None = None,
     ) -> None:
         models = list(_state(self._view).models.values())
         for model in models:
             if model is None:
                 continue
             updates = {
                 "freeze": bool(freeze),
                 "frozen_position": (
                     (frozen_positions or {}).get(model.id) if freeze else None
                 ),
             }
             if new_offsets is not None and model.id in new_offsets:
                 offset = new_offsets.get(model.id)
                 if offset is not None:
                     updates["offset_relative"] = offset
             update_magnifier_model(
                 self._view,
                 self._render,
                 model.id,
                 **updates,
             )

     def set_active_magnifier_offset(self, offset: Point):
         model = self.ensure_active_magnifier()
         if model is None:
             return None
         return update_magnifier_model(
             self._view,
             self._render,
             model.id,
             offset_relative=offset,
         )

     def set_active_magnifier_spacing(self, spacing: float):
         model = self.ensure_active_magnifier()
         if model is None:
             return None
         return update_magnifier_model(
             self._view,
             self._render,
             model.id,
             spacing_relative=float(spacing),
         )

     def update_active_magnifier_combined_state(self):
         model = self.ensure_active_magnifier(create_if_missing=False)
         if model is None or not magnifier_enabled(self._view):
             return False
         return (
             bool(model.visible_left)
             and bool(model.visible_right)
             and float(model.spacing_relative) <= self.THRESHOLD + 1e-5
         )

     def is_active_magnifier_combined(self) -> bool:
         model = self.get_active_or_first_magnifier()
         if model is None or not magnifier_enabled(self._view):
             return False
         interaction = getattr(self.store.viewport, "interaction_state", None)
         use_visual = (
             interaction is not None
             and bool(getattr(interaction, "is_interactive_mode", False))
             and bool(getattr(self._view, "optimize_interactive_movement", True))
         )
         effective_spacing = (
             float(
                 getattr(
                     interaction,
                     "interactive_spacing_relative_visual",
                     model.spacing_relative,
                 )
             )
             if use_visual
             else float(model.spacing_relative)
         )
         return (
             bool(model.visible_left)
             and bool(model.visible_right)
             and effective_spacing <= self.THRESHOLD + 1e-5
         )

     def get_active_source_position(self) -> Point:
         model = self.get_active_or_first_magnifier()
         return model.position if model is not None else Point(0.5, 0.5)

     def get_active_offset(self) -> Point:
         model = self.get_active_or_first_magnifier()
         return model.offset_relative if model is not None else Point(0.0, 0.0)

     def get_active_spacing(self) -> float:
         model = self.get_active_or_first_magnifier()
         return float(model.spacing_relative) if model is not None else 0.0

     def get_active_frozen_position(self) -> Point | None:
         model = self.get_active_or_first_magnifier()
         return model.frozen_position if model is not None else None

Index: src/tabs/image_compare/canvas/shaders/base_array.frag
===================================================================
--- src/tabs/image_compare/canvas/shaders/base_array.frag	
+++ src/tabs/image_compare/canvas/shaders/base_array.frag	
@@ -0,0 +1,149 @@
+#version 440
+
+// Multi-tile counterpart to base.frag (docs/dev/rendering/
+// tile-array-atlas-plan.md Phase 2). Per-pixel comparison logic
+// (split/diff/channel) is identical to base.frag; the only difference is
+// that image1/image2/imageDiff are layers of one shared texture array
+// (sampler2DArray) instead of three separate whole-texture sampler2D
+// bindings, addressed by this instance's iLayers. Tile content is
+// uploaded 1:1 (no resampling) into the top-left corner of a
+// fixed-size array layer (see resources.py's _ARRAY_LAYER_PX), so
+// texel-space math (computeEdge's step size, mip selection) is
+// unaffected by content-scale -- content-scale only rescales the UV
+// used to *address* that corner.
+
+layout(std140, binding = 0) uniform UBuf
+{
+    mat4 mvp;
+    vec2 offset;
+    vec2 zoom;
+    float splitPosition;
+    vec4 letterbox1;
+    vec4 letterbox2;
+    int isHorizontal;
+    int channelMode;
+    int diffMode;
+    int diffSourceReady;
+    float diffThreshold;
+    vec4 canvasLetterbox;
+    vec4 letterboxFill;
+};
+
+layout(binding = 1) uniform sampler2DArray tileArray;
+
+layout(location = 0) in vec2 vTexCoord;
+layout(location = 1) in vec4 vRect1;
+layout(location = 2) in vec4 vRect2;
+layout(location = 3) in vec4 vContentScale;
+layout(location = 4) in vec2 vContentScaleDiff;
+layout(location = 5) flat in ivec3 vLayers;
+layout(location = 6) in vec4 vRectDiff;
+
+layout(location = 0) out vec4 fragColor;
+
+vec4 applyChannel(vec4 color, int mode)
+{
+    if (mode == 1) return vec4(color.r, 0.0, 0.0, color.a);
+    if (mode == 2) return vec4(0.0, color.g, 0.0, color.a);
+    if (mode == 3) return vec4(0.0, 0.0, color.b, color.a);
+    if (mode == 4) {
+        float luma = dot(color.rgb, vec3(0.299, 0.587, 0.114));
+        return vec4(luma, luma, luma, color.a);
+    }
+    return color;
+}
+
+float luminance(vec3 color)
+{
+    return dot(color, vec3(0.299, 0.587, 0.114));
+}
+
+vec4 sampleArray(int layer, vec2 uv)
+{
+    return applyChannel(texture(tileArray, vec3(uv, float(layer))), channelMode);
+}
+
+vec4 computeEdgeArray(int layer, vec2 uv)
+{
+    vec2 stepPx = 1.0 / vec2(textureSize(tileArray, 0).xy);
+    float tl = luminance(sampleArray(layer, uv + vec2(-stepPx.x, -stepPx.y)).rgb);
+    float t  = luminance(sampleArray(layer, uv + vec2(0.0, -stepPx.y)).rgb);
+    float tr = luminance(sampleArray(layer, uv + vec2(stepPx.x, -stepPx.y)).rgb);
+    float l  = luminance(sampleArray(layer, uv + vec2(-stepPx.x, 0.0)).rgb);
+    float r  = luminance(sampleArray(layer, uv + vec2(stepPx.x, 0.0)).rgb);
+    float bl = luminance(sampleArray(layer, uv + vec2(-stepPx.x, stepPx.y)).rgb);
+    float b  = luminance(sampleArray(layer, uv + vec2(0.0, stepPx.y)).rgb);
+    float br = luminance(sampleArray(layer, uv + vec2(stepPx.x, stepPx.y)).rgb);
+    float gx = -tl - 2.0 * l - bl + tr + 2.0 * r + br;
+    float gy = -tl - 2.0 * t - tr + bl + 2.0 * b + br;
+    float edge = smoothstep(0.05, 0.3, sqrt(gx * gx + gy * gy));
+    return vec4(edge, edge, edge, 1.0);
+}
+
+void main()
+{
+    vec2 center = vec2(0.5);
+    vec2 uv = (vTexCoord - center) / zoom + center - offset;
+    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
+        fragColor = vec4(0.0);
+        return;
+    }
+
+    vec2 splitUV = (uv - letterbox1.xy) / letterbox1.zw;
+    bool useFirst = (isHorizontal != 0 ? splitUV.y : splitUV.x) < splitPosition;
+    vec4 letterbox = useFirst ? letterbox1 : letterbox2;
+    vec2 sampleUV = (uv - letterbox.xy) / letterbox.zw;
+    if (sampleUV.x < 0.0 || sampleUV.x > 1.0 || sampleUV.y < 0.0 || sampleUV.y > 1.0) {
+        if (canvasLetterbox.z > 0.0 && canvasLetterbox.w > 0.0 && letterboxFill.a > 0.0) {
+            vec2 canvasUV = (uv - canvasLetterbox.xy) / canvasLetterbox.zw;
+            if (canvasUV.x >= 0.0 && canvasUV.x <= 1.0 && canvasUV.y >= 0.0 && canvasUV.y <= 1.0) {
+                fragColor = letterboxFill;
+                return;
+            }
+        }
+        fragColor = vec4(0.0);
+        return;
+    }
+
+    vec2 tileUV1 = (sampleUV - vRect1.xy) / vRect1.zw;
+    vec2 tileUV2 = (sampleUV - vRect2.xy) / vRect2.zw;
+    if (diffMode != 4) {
+        bool inTile1 = tileUV1.x >= 0.0 && tileUV1.x <= 1.0 && tileUV1.y >= 0.0 && tileUV1.y <= 1.0;
+        bool inTile2 = tileUV2.x >= 0.0 && tileUV2.x <= 1.0 && tileUV2.y >= 0.0 && tileUV2.y <= 1.0;
+        if (!inTile1 || !inTile2) {
+            fragColor = vec4(0.0);
+            return;
+        }
+    }
+
+    vec2 arrUV1 = tileUV1 * vContentScale.xy;
+    vec2 arrUV2 = tileUV2 * vContentScale.zw;
+
+    vec4 color1 = sampleArray(vLayers.x, arrUV1);
+    vec4 color2 = sampleArray(vLayers.y, arrUV2);
+
+    if (diffMode == 1) {
+        vec3 diff = abs(color1.rgb - color2.rgb);
+        float maxDiff = max(diff.r, max(diff.g, diff.b));
+        fragColor = maxDiff > diffThreshold ? vec4(1.0, 0.35, 0.47, 1.0) : color1;
+    } else if (diffMode == 2) {
+        vec3 diff = abs(color1.rgb - color2.rgb);
+        float gray = clamp(luminance(diff) * 4.0, 0.0, 1.0);
+        fragColor = vec4(gray, gray, gray, 1.0);
+    } else if (diffMode == 3) {
+        fragColor = useFirst ? computeEdgeArray(vLayers.x, arrUV1) : computeEdgeArray(vLayers.y, arrUV2);
+    } else if (diffMode == 4 && diffSourceReady != 0) {
+        // vRectDiff = (0,0,1,1) (identity) when diff isn't split into
+        // multiple tiles, so this reduces to the old `sampleUV *
+        // vContentScaleDiff` exactly. Clamp rather than discard at the
+        // tile's own edge: this instance's on-screen footprint is already
+        // clipped to its assigned diff tile via iBBox, so any out-of-[0,1]
+        // here is float rounding at that boundary, not a real sampling
+        // error -- clamping avoids a seam a discard would leave.
+        vec2 tileUVDiff = clamp((sampleUV - vRectDiff.xy) / vRectDiff.zw, 0.0, 1.0);
+        vec2 arrUVDiff = tileUVDiff * vContentScaleDiff;
+        fragColor = sampleArray(vLayers.z, arrUVDiff);
+    } else {
+        fragColor = useFirst ? color1 : color2;
+    }
+}

Index: src/tabs/image_compare/canvas/shaders/base_array.vert
===================================================================
--- src/tabs/image_compare/canvas/shaders/base_array.vert	
+++ src/tabs/image_compare/canvas/shaders/base_array.vert	
@@ -0,0 +1,94 @@
+#version 440
+
+// Multi-tile counterpart to base.vert (docs/dev/rendering/
+// tile-array-atlas-plan.md Phase 2). One instanced draw replaces N
+// per-tile-pair draw calls; per-instance data carries what used to be a
+// whole draw call's own uniform slot (tileRect1/2 + which texture-array
+// layer each side samples).
+//
+// Phase 10 (overdraw fix): position/texCoord are no longer a shared
+// fullscreen quad emitted unclipped by every instance. Each instance now
+// carries its own content-space bounding box (iBBox -- rect1's and rect2's
+// on-screen footprints intersected, computed CPU-side in
+// build_array_draw_plan/_intersection_rect since that's the only region
+// base_array.frag's tileUV1/tileUV2 discard could ever let through for
+// this instance anyway). texCoord's 0/1 corner selector picks a corner of
+// iBBox instead of the full [0,1] canvas, and the result is mapped back
+// through the inverse of base_array.frag's ``uv = (vTexCoord - center) /
+// zoom + center - offset`` to get the screen-space vTexCoord/gl_Position
+// that would have produced that content-space corner -- so vTexCoord's
+// meaning is unchanged and base_array.frag needs no changes at all, it
+// just now runs over a triangle sized to the instance's real footprint
+// instead of the whole framebuffer. One instance is always given
+// iBBox = (0,0,1,1) by the caller (render()) regardless of its actual
+// footprint, to guarantee at least one instance still covers
+// canvasLetterbox/letterboxFill's pillarbox background-fill area, which
+// depends only on uniforms (not on any instance's own tile rect) and so is
+// painted correctly by any fullscreen instance.
+
+layout(location = 0) in vec2 position;
+layout(location = 1) in vec2 texCoord;
+
+// Per-instance.
+layout(location = 2) in vec4 iRect1;
+layout(location = 3) in vec4 iRect2;
+// xy = image1 content-scale (contentPx / arrayLayerPx), zw = image2's.
+layout(location = 4) in vec4 iContentScale;
+layout(location = 5) in vec2 iContentScaleDiff;
+// x = layer1, y = layer2, z = layerDiff (unused unless diffMode == 4).
+layout(location = 6) in ivec3 iLayers;
+// Content-space (xy = origin, zw = size) bounding box this instance's
+// geometry is clipped to -- see file header comment.
+layout(location = 7) in vec4 iBBox;
+// The diff/SSIM tile this instance samples, in the same content-space as
+// iRect1/iRect2 (xy = origin, zw = size) -- identity (0,0,1,1) when diff
+// isn't split into multiple tiles, matching the old direct-sampleUV
+// behavior exactly. Needed because a diff source can have its own tile
+// grid finer than iBBox's (build_array_draw_plan splits one draw instance
+// per overlapping diff tile): without subtracting this tile's own origin
+// first, base_array.frag sampled every diff-tile instance with the same
+// whole-canvas UV regardless of which tile it was assigned, showing each
+// tile's content at the wrong, effectively-random offset within itself
+// (docs/dev/rendering/qrhi-gotchas.md #ssim-diff-blocky-mosaic-at-coarse-lod).
+layout(location = 8) in vec4 iRectDiff;
+
+layout(std140, binding = 0) uniform UBuf
+{
+    mat4 mvp;
+    vec2 offset;
+    vec2 zoom;
+    float splitPosition;
+    vec4 letterbox1;
+    vec4 letterbox2;
+    int isHorizontal;
+    int channelMode;
+    int diffMode;
+    int diffSourceReady;
+    float diffThreshold;
+    vec4 canvasLetterbox;
+    vec4 letterboxFill;
+};
+
+layout(location = 0) out vec2 vTexCoord;
+layout(location = 1) out vec4 vRect1;
+layout(location = 2) out vec4 vRect2;
+layout(location = 3) out vec4 vContentScale;
+layout(location = 4) out vec2 vContentScaleDiff;
+layout(location = 5) flat out ivec3 vLayers;
+layout(location = 6) out vec4 vRectDiff;
+
+void main()
+{
+    vec2 center = vec2(0.5);
+    vec2 targetUV = iBBox.xy + texCoord * iBBox.zw;
+    vec2 screenUV = (targetUV - center + offset) * zoom + center;
+    vec2 position2 = vec2(screenUV.x * 2.0 - 1.0, 1.0 - screenUV.y * 2.0);
+    gl_Position = mvp * vec4(position2, 0.0, 1.0);
+    vTexCoord = screenUV;
+    vRect1 = iRect1;
+    vRect2 = iRect2;
+    vContentScale = iContentScale;
+    vContentScaleDiff = iContentScaleDiff;
+    vLayers = iLayers;
+    vRectDiff = iRectDiff;
+}

