         updated_cut_timestamps: list[float] = []
         for ts in self._cut_timestamps:
             ts = float(ts)
             if ts < start_time:
                 updated_cut_timestamps.append(ts)
                 continue
             if shift > 0.0 and ts >= end_time:
                 updated_cut_timestamps.append(ts - shift)

