     node: LayoutNode,
     slots_by_id: dict[int, CompareSlot],
 ) -> float | None:
     """Natural aspect ratio for a leaf/subtree, ignoring divider gaps."""
     if isinstance(node, LeafNode):
         slot = slots_by_id.get(node.slot_id)
