     *,
     source_widget,
     global_pos,
     entries: tuple[ContextMenuEntry, ...],
     key: object,
     on_triggered=None,
 ) -> ContextMenu | None:
     return get_context_menu_manager().open_entries(
         source_widget=source_widget,
         global_pos=global_pos,
         entries=entries,
         key=key,
         on_triggered=on_triggered,
