            yield block, cwd
        elif block.get("type") == "tool_use_group" or "tools" in block:
            tools = block.get("tools") or []
            for t in tools:
                if isinstance(t, dict) and t.get("type") == "tool_use":
                    yield t, cwd


def parse_bash(command, cwd, ops):
    if not in_repo(cwd):
        return
    m = RM_RE.search(command)
    if m:
        for tok in re.findall(r"\S+", m.group(1)):
            tok = tok.strip("\"'")
            path = tok if tok.startswith("/") else f"{cwd}/{tok}"
            if in_repo(path) and ".." not in path.split("/"):
                ops.append({"t": "D", "path": path, "status": "completed"})
        return
    m = MV_RE.search(command)
    if m:
        src, dst = m.group(1), m.group(2)
        src = src if src.startswith("/") else f"{cwd}/{src}"
        dst = dst if dst.startswith("/") else f"{cwd}/{dst}"
        if in_repo(src) and in_repo(dst):
            ops.append({"t": "M", "src": src, "dst": dst, "status": "completed"})


def main():
    ops = []
    for path in sorted(glob.glob(JSONL_DIR + "/*.jsonl")):
        with open(path, encoding="utf-8", errors="replace") as f:
            for lineno, line in enumerate(f, 1):
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                ts = obj.get("timestamp", "")
                msg = obj.get("message", {})
                cwd = (obj.get("cwd") or "").strip() or None
                if cwd is None and obj.get("type") == "assistant":
                    cwd = None
                content = msg.get("content") if isinstance(msg, dict) else None
                if not isinstance(content, list):
                    continue
                for block, _ in walk_blocks(content, cwd or ""):
                    name = block.get("name")
                    inp = block.get("input") or {}
                    if name == "Write" and isinstance(inp.get("file_path"), str):
                        ops.append(
                            {"ts": ts, "t": "W", "path": inp["file_path"],
                             "content": inp.get("content", ""), "status": "completed"}
                        )
                    elif name == "Edit" and isinstance(inp.get("file_path"), str):
                        ops.append(
                            {"ts": ts, "t": "E", "path": inp["file_path"],
                             "old": inp.get("old_string", ""), "new": inp.get("new_string", ""),
                             "status": "completed"}
                        )
                    elif name == "Bash" and isinstance(inp.get("command"), str):
                        parse_bash(inp["command"], cwd or "/home/jorj/Загрузки/Improve-ImgSLI", ops)

    ops.sort(key=lambda o: (o.get("ts", ""), o.get("t", "")))
    with open(OUT, "w", encoding="utf-8") as f:
        for op in ops:
            f.write(json.dumps(op, ensure_ascii=False) + "\n")
    kinds = {}
    for op in ops:
        kinds[op["t"]] = kinds.get(op["t"], 0) + 1
    print(f"claude ops: {len(ops)} | {kinds}")


if __name__ == "__main__":
    main()

"""Replay extracted ops over the fresh clone to reconstruct the working tree.

Merges /tmp/opencode/ops.jsonl (opencode) + /tmp/opencode/claude_ops.jsonl
(Claude Desktop), sorts by timestamp, applies W/E/D/M ops to
/home/jorj/Загрузки/Improve-ImgSLI. Reports misses (edit oldString not
found) and dangerous ops for manual review.
"""

import json
import os
import shutil
import sys
from pathlib import Path

BASE = Path("/home/jorj/Загрузки/Improve-ImgSLI")
OPS = ["/tmp/opencode/ops.jsonl", "/tmp/opencode/claude_ops.jsonl"]


def load():
    ops = []
    for f in OPS:
        if not os.path.exists(f):
            continue
        with open(f, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line:
                    ops.append(json.loads(line))
    ops.sort(key=lambda o: (o.get("ts", ""), o.get("t", ""), o.get("path", "")))
    return ops


def apply_write(op):
    path = BASE / op["path"].lstrip("/")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(op["content"].encode("utf-8") if isinstance(op["content"], str) else op["content"])
    return True


def apply_edit(op):
    path = BASE / op["path"].lstrip("/")
    if not path.is_file():
        return False
    content = path.read_text(encoding="utf-8")
    old = op["old"]
    if old not in content:
        return False
    path.write_text(content.replace(old, op["new"], 1), encoding="utf-8")
    return True


def apply_delete(op):
    path = BASE / op["path"].lstrip("/")
    if not path.exists():
        return False
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
    else:
        path.unlink()
    return True


def apply_move(op):
    src = BASE / op["src"].lstrip("/")
    dst = BASE / op["dst"].lstrip("/")
    if not src.exists():
        return False
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dst))
    return True


def main():
    ops = load()
    stats = {"W": 0, "E": 0, "D": 0, "M": 0}
    misses = []
    dangerous = []
    for op in ops:
        t = op["t"]
        if op.get("status") != "completed" and t != "DANGEROUS":
            continue
        if t == "W":
            if apply_write(op):
                stats["W"] += 1
            else:
                misses.append(("W", op.get("path")))
        elif t == "E":
            if apply_edit(op):
                stats["E"] += 1
            else:
                misses.append(("E", op.get("path")))
        elif t == "D":
            if apply_delete(op):
                stats["D"] += 1
        elif t == "M":
            if apply_move(op):
                stats["M"] += 1
        elif t == "DANGEROUS":
            dangerous.append(op.get("command"))
    print("applied:", stats)
    print(f"misses: {len(misses)}")
    for kind, path in misses[:40]:
        print("  MISS", kind, path)
    print(f"dangerous bash ops: {len(dangerous)}")
    for c in dangerous[:5]:
        print("  DANGEROUS:", c)


if __name__ == "__main__":
    main()

