"""Recovery engine v2: full-chronology replay with git semantics.

Extracts EVERYTHING (write/edit tools + bash commands) from both sources,
sorts by timestamp, and replays onto the fresh clone with git-aware
handling: mv/rm/touch, git checkout -- (restores from last commit
snapshot), git stash push/pop, git reset --hard, git commit (snapshot).

Only paths under /home/jorj/Загрузки/Improve-ImgSLI are touched.
"""

import datetime
import glob
import json
import os
import re
import shutil
import sqlite3
from pathlib import Path

BASE = Path("/home/jorj/Загрузки/Improve-ImgSLI")
REPO_PREFIX = str(BASE) + "/"
OPENDOCE_DB = "/home/jorj/.local/share/opencode/opencode.db"
CLAUDE_DIR = "/home/jorj/.claude/projects/-home-jorj----------Improve-ImgSLI"
LOG = "/tmp/opencode/engine.log"


def log(msg):
    with open(LOG, "a", encoding="utf-8") as f:
        f.write(msg + "\n")


def iso_to_ms(ts: str) -> int:
    try:
        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        return int(dt.timestamp() * 1000)
    except Exception:
        return 0


def in_repo(path: str) -> bool:
    return path == str(BASE) or path.startswith(REPO_PREFIX)


def rel(path: str) -> str:
    return path[len(REPO_PREFIX):] if path.startswith(REPO_PREFIX) else None


def split_stmts(line: str) -> list[str]:
    """Split on ; && || outside quotes."""
    stmts = []
    cur = []
    quote = None
    i = 0
    while i < len(line):
        ch = line[i]
        if quote:
            cur.append(ch)
            if ch == quote:
                quote = None
            i += 1
            continue
        if ch in "\"'":
            quote = ch
            cur.append(ch)
            i += 1
            continue
        if line.startswith("&&", i) or line.startswith("||", i) or ch == ";":
            stmts.append("".join(cur).strip())
            cur = []
            i += 2 if line.startswith(("&&", "||"), i) else 1
            continue
        cur.append(ch)
        i += 1
    stmts.append("".join(cur).strip())
    return [s for s in stmts if s]


def shell_words(s: str) -> list[str]:
    return [w.strip("\"'") for w in re.findall(r"'[^']*'|\"[^\"]*\"|\S+", s)]


def strip_heredocs(cmd: str) -> str:
    """Remove heredoc bodies (python blocks) so shell parsing doesn't see them."""
    lines = cmd.split("\n")
    out = []
    skip_until = None
    for line in lines:
        if skip_until:
            if line.strip() == skip_until:
                skip_until = None
            continue
        m = re.search(r"<<-?\s*['\"]?([A-Za-z_][A-Za-z0-9_]*)['\"]?", line)
        if m:
            skip_until = m.group(1)
            out.append(line.split("<<", 1)[0])
            continue
        out.append(line)
    return "\n".join(out)


def parse_bash(cmd: str, events_ts: int, engine_events: list):
    cmd = strip_heredocs(cmd)
    cwd = str(BASE)
    if "cd " in cmd:
        m = re.search(r"cd\s+([^\s;&|]+)", cmd)
        if m:
            target = m.group(1).strip("\"'")
            if target == "/home/jorj/Загрузки/Improve-ImgSLI" or target == str(BASE):
                cwd = str(BASE)

    def resolve(p: str) -> str | None:
        if p.startswith("/"):
            return p
        return f"{cwd}/{p}" if not p.startswith("..") else None

    for stmt in split_stmts(cmd):
        words = shell_words(stmt)
        if not words:
            continue
        head = words[0]
        if head == "git" and len(words) >= 2:
            sub = words[1]
            if sub == "mv" and len(words) >= 4:
                srcs, dst = words[2:-1], words[-1]
                for s in srcs:
                    sp, dp = resolve(s), resolve(dst)
                    if sp and dp and in_repo(sp) and in_repo(dp):
                        engine_events.append({"ts": events_ts, "kind": "move",
                                              "src": rel(sp), "dst": rel(dp)})
            elif sub == "rm":
                paths = [p for p in words[2:] if not p.startswith("-")]
                for p in paths:
                    sp = resolve(p)
                    if sp and in_repo(sp):
                        engine_events.append({"ts": events_ts, "kind": "delete", "path": rel(sp)})
            elif sub == "checkout":
                paths = [p for p in words[2:] if not p.startswith("-") and p != "--"]
                if paths:
                    engine_events.append({"ts": events_ts, "kind": "checkout", "paths": [
                        rel(resolve(p)) for p in paths if resolve(p) and in_repo(resolve(p))]})
            elif sub == "reset":
                if "--hard" in words:
                    engine_events.append({"ts": events_ts, "kind": "reset_hard"})
            elif sub == "stash":
                rest = words[2:]
                if rest and rest[0] in ("pop", "apply"):
                    engine_events.append({"ts": events_ts, "kind": "stash_pop"})
                elif rest and rest[0] in ("drop", "clear"):
                    engine_events.append({"ts": events_ts, "kind": "stash_clear"})
                elif rest and rest[0] == "list":
                    pass
                else:
                    paths = []
                    if "--" in rest:
                        paths = [rel(resolve(p)) for p in rest[rest.index("--") + 1:]
                                 if resolve(p) and in_repo(resolve(p))]
                    engine_events.append({"ts": events_ts, "kind": "stash_push", "paths": paths})
            elif sub == "commit":
                engine_events.append({"ts": events_ts, "kind": "commit"})
        elif head in ("mv",):
            if len(words) >= 3:
                srcs, dst = words[1:-1], words[-1]
                for s in srcs:
                    sp, dp = resolve(s), resolve(dst)
                    if sp and dp and in_repo(sp) and in_repo(dp):
                        engine_events.append({"ts": events_ts, "kind": "move",
                                              "src": rel(sp), "dst": rel(dp)})
        elif head == "rm":
            paths = [p for p in words[1:] if not p.startswith("-")]
            for p in paths:
                sp = resolve(p)
                if sp and in_repo(sp):
                    engine_events.append({"ts": events_ts, "kind": "delete", "path": rel(sp)})
        elif head == "rmdir":
            for p in words[1:]:
                sp = resolve(p)
                if sp and in_repo(sp):
                    engine_events.append({"ts": events_ts, "kind": "delete", "path": rel(sp)})
        elif head == "touch":
            for p in words[1:]:
                sp = resolve(p)
                if sp and in_repo(sp):
                    engine_events.append({"ts": events_ts, "kind": "write",
                                          "path": rel(sp), "content": ""})


def collect_events() -> list:
    events = []
    # opencode
    con = sqlite3.connect(OPENDOCE_DB)
    cur = con.cursor()
    sessions = cur.execute(
        "SELECT id, time_created, directory FROM session WHERE directory LIKE '%Improve-ImgSLI%' ORDER BY time_created"
    ).fetchall()
    for sid, stime, directory in sessions:
        parts = cur.execute(
            "SELECT time_created, data FROM part WHERE session_id=? ORDER BY time_created", (sid,)
        ).fetchall()
        for ptime, data in parts:
            try:
                j = json.loads(data)
            except Exception:
                continue
            if j.get("type") != "tool":
                continue
            state = j.get("state", {})
            tool = j.get("tool")
            inp = state.get("input", {})
            if tool == "write" and isinstance(inp.get("filePath"), str):
                p = inp["filePath"]
                if in_repo(p):
                    events.append({"ts": ptime, "kind": "write", "path": rel(p),
                                   "content": inp.get("content", "")})
            elif tool == "edit" and isinstance(inp.get("filePath"), str):
                p = inp["filePath"]
                if in_repo(p):
                    events.append({"ts": ptime, "kind": "edit", "path": rel(p),
                                   "old": inp.get("oldString", ""), "new": inp.get("newString", "")})
            elif tool == "bash" and isinstance(inp.get("command"), str):
                parse_bash(inp["command"], ptime, events)
    # claude
    for path in glob.glob(CLAUDE_DIR + "/*.jsonl"):
        for line in open(path, encoding="utf-8", errors="replace"):
            try:
                obj = json.loads(line)
            except Exception:
                continue
            ts = iso_to_ms(obj.get("timestamp", ""))
            msg = obj.get("message", {})
            content = msg.get("content") if isinstance(msg, dict) else None
            if not isinstance(content, list):
                continue
            for block in content:
                if not isinstance(block, dict) or block.get("type") != "tool_use":
                    continue
                name = block.get("name")
                inp = block.get("input") or {}
                if name == "Write" and isinstance(inp.get("file_path"), str):
                    p = inp["file_path"]
                    if in_repo(p):
                        events.append({"ts": ts, "kind": "write", "path": rel(p),
                                       "content": inp.get("content", "")})
                elif name == "Edit" and isinstance(inp.get("file_path"), str):
                    p = inp["file_path"]
                    if in_repo(p):
                        events.append({"ts": ts, "kind": "edit", "path": rel(p),
                                       "old": inp.get("old_string", ""),
                                       "new": inp.get("new_string", "")})
                elif name == "Bash" and isinstance(inp.get("command"), str):
                    parse_bash(inp["command"], ts, events)
    events.sort(key=lambda e: e["ts"])
    return events


class Engine:
    def __init__(self):
        self.files: dict[str, bytes] = {}
        self.committed: dict[str, bytes] | None = None
        self.stash_stack: list[dict[str, bytes]] = []
        self.stats = {"write": 0, "edit": 0, "edit_miss": 0, "delete": 0,
                      "move": 0, "checkout": 0, "stash": 0, "commit": 0}
        self.misses: list[str] = []

    def write(self, path, content):
        self.files[path] = content.encode("utf-8") if isinstance(content, str) else content
        self.stats["write"] += 1

    def edit(self, path, old, new):
        if path not in self.files:
            self.misses.append(f"E nofile {path}")
            self.stats["edit_miss"] += 1
            return
        content = self.files[path].decode("utf-8", errors="replace")
        if old not in content:
            self.misses.append(f"E nomatch {path}")
            self.stats["edit_miss"] += 1
            return
        self.files[path] = content.replace(old, new, 1).encode("utf-8")
        self.stats["edit"] += 1

    def delete(self, path):
        removed = [p for p in self.files if p == path or p.startswith(path + "/")]
        for p in removed:
            del self.files[p]
        self.stats["delete"] += len(removed)

    def move(self, src, dst):
        if src not in self.files:
            self.misses.append(f"M nofile {src}")
            return
        content = self.files.pop(src)
        self.files[dst] = content
        self.stats["move"] += 1

    def checkout(self, paths):
        if self.committed is None:
            self.misses.append(f"checkout before any commit: {paths}")
            return
        for p in paths:
            if p in self.committed:
                self.files[p] = self.committed[p]
            else:
                self.files.pop(p, None)
            self.stats["checkout"] += 1

    def stash_push(self, paths):
        if paths:
            stash = {p: self.files[p] for p in paths if p in self.files}
            for p in paths:
                self.files.pop(p, None)
        else:
            stash = dict(self.files)
            self.files = {}
        self.stash_stack.append(stash)
        self.stats["stash"] += 1

    def stash_pop(self):
        if not self.stash_stack:
            self.misses.append("stash pop with empty stack")
            return
        stash = self.stash_stack.pop()
        self.files.update(stash)
        self.stats["stash"] += 1

    def commit(self):
        self.committed = dict(self.files)
        self.stats["commit"] += 1

    def reset_hard(self):
        if self.committed is not None:
            self.files = dict(self.committed)

    def flush(self):
        for path, content in sorted(self.files.items()):
            target = BASE / path
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)


def main():
    events = collect_events()
    log(f"total events: {len(events)}")
    kinds = {}
    for e in events:
        kinds[e["kind"]] = kinds.get(e["kind"], 0) + 1
    log(f"event kinds: {kinds}")

    engine = Engine()
    for e in events:
        k = e["kind"]
        if k == "write":
            engine.write(e["path"], e["content"])
        elif k == "edit":
            engine.edit(e["path"], e["old"], e["new"])
        elif k == "delete":
            engine.delete(e["path"])
        elif k == "move":
            engine.move(e["src"], e["dst"])
        elif k == "checkout":
            engine.checkout(e["paths"])
        elif k == "stash_push":
            engine.stash_push(e["paths"])
        elif k == "stash_pop":
            engine.stash_pop()
        elif k == "stash_clear":
            engine.stash_stack = []
        elif k == "commit":
            engine.commit()
        elif k == "reset_hard":
            engine.reset_hard()

    engine.flush()
    log(f"stats: {engine.stats}")
    log(f"misses: {len(engine.misses)}")
    for m in engine.misses[:60]:
        log(f"  MISS {m}")
    print("stats:", engine.stats)
    print("misses:", len(engine.misses))
    for m in engine.misses[:40]:
        print("  MISS", m)


if __name__ == "__main__":
    main()

