def parse_sed(stmt: str, words: list[str], cwd: str, events_ts: int, engine_events: list):
    """Handle `sed -i 's/OLD/NEW/g' file...` — record regex substitution ops.

    Supports multiple `;`-separated expressions in one arg (incl. `-e`),
    and `N s|...|...|g` line-prefixed forms.
    """
    i = 1
    exprs: list[str] = []
    while i < len(words):
        w = words[i]
        if w.startswith("-"):
            i += 1
            continue
        if w in ("-e", "-E", "-r"):
            i += 1
            continue
        if w == "-i" or w.startswith("-i"):
            i += 1
            continue
        exprs.append(w)
        i += 1
    if not exprs:
        return
    file_args = exprs[1:]
    for expr in exprs[0].split(";"):
        m = re.match(r"^(\d*)s([^\\])(.*?)\2(.*?)\2([gIp]?)$", expr)
        if not m:
            continue
        lineno_s, delim, pat, repl, flags = m.groups()
        if not pat:
            continue
        try:
            re.compile(pat)
        except re.error:
            continue
        for f in file_args:
            if f.startswith("/"):
                p = f
            elif not f.startswith(".."):
                p = f"{cwd}/{f}"
            else:
                continue
            if not in_repo(p):
                continue
            r = rel(p)
            if not r:
                continue
            engine_events.append({
                "ts": events_ts, "kind": "sed", "path": r,
                "pattern": pat, "replacement": repl, "line": lineno_s or None,
            })

