def parse_sed(stmt: str, words: list[str], cwd: str, events_ts: int, engine_events: list):
    """Handle `sed -i 's/OLD/NEW/g' file...` — record a regex substitution op."""
    i = 1
    while i < len(words) and words[i].startswith("-"):
        i += 1
    if i >= len(words):
        return
    expr = words[i]
    files = words[i + 1:]
    m = re.match(r"^(\d*)s([^\\])(.*?)\2(.*?)\2([gIp]?)$", expr)
    if not m:
        return
    lineno_s, delim, pat, repl, flags = m.groups()
    try:
        pattern = re.compile(pat)
    except re.error:
        return
    for f in files:
        if f.startswith("/"):
            p = f
        elif not f.startswith(".."):
            p = f"{cwd}/{f}"
        else:
            continue
        if not in_repo(p):
            continue
        r = rel(p)
        if not r:
            continue
        engine_events.append({
            "ts": events_ts, "kind": "sed", "path": r,
