         offset: int = 6,
         margin: int = 8,
     ) -> QRect:
         anchor_rect = self.anchor_global_rect(anchor_widget)
         host_window = self._host.window()
         bounds = host_window.frameGeometry().adjusted(margin, margin, -margin, -margin)
