     def cancel_drag(self):
         if not self._is_dragging:
             return

         self._cleanup()

     def _cleanup(self):

         if self._ghost_widget:
             self._ghost_widget.deleteLater()
             self._ghost_widget = None

         if self._source_widget and sip.isValid(self._source_widget):
             try:
