             try:
                 if hasattr(self._current_target, "clear_drop_indicator"):
                     self._current_target.clear_drop_indicator()
             except RuntimeError:
                 pass

         self._is_dragging = False
         self._source_data = None
         self._current_target = None
         self._source_widget = None

