 PREVIEW_LEGACY_MEMBERS = ("preview.jpg",)
 PREVIEW_MEMBERS = (PREVIEW_MEMBER, *PREVIEW_LEGACY_MEMBERS)
 PREVIEW_WIDTH = 160
