     action_id: str,
     *,
     default: str | None,
     overrides: Mapping[str, str] | None,
 ) -> str | None:
     overrides = overrides or {}
     if action_id in overrides:
         normalized = normalize_sequence(overrides[action_id])
         return normalized or None
     normalized = normalize_sequence(default)
     return normalized or None


