         return 0
     total = 0
     for token in tokens:
         best: int | None = None
         for text in haystacks:
             rank = _rank_token_in_text(text, token)
             if rank is not None:
                 best = rank if best is None else min(best, rank)
         if best is None:
             return None
         total += best
