                     if anchor is not None:
                         toast_manager.set_anchor(anchor)

         handled = (
             self._tab_registry.apply_host_session_mode(
                 session_type,
                 self,
                 session_title=session_title,
             )
             if self._tab_registry
             else False
         )
         if not handled:
