 _TR_PLACEHOLDER_RE = re.compile(r"\{\{tr:([a-zA-Z0-9_.]+)\}\}")
 _IMG_PLACEHOLDER_RE = re.compile(r"\{\{img:([a-zA-Z0-9_.]+)\}\}")

