         if not self._actions:
             return
         values = [data for _label, data in self._actions]
         try:
             index = values.index(self._current)
         except ValueError:
             index = -1
         next_data = values[(index + 1) % len(values)]
         self._current = next_data
         self.selected.emit(next_data)

