     decode finishes (``scene.store.ReplaceSlotImage``). Small/fast sources
     skip the preview tier and go straight to ``TiledPixelStore``.
     """

     id: int
     path: Path | None = None
     label: str = ""
     image: "TiledPixelStore | QImage | None" = None

     @property
     def is_loaded(self) -> bool:
         return self.image is not None

     @property
     def is_preview_only(self) -> bool:
         from PySide6.QtGui import QImage

         return isinstance(self.image, QImage)


 @dataclass
 class LeafNode:
     """Holds a single image slot reference."""

     slot_id: int


 @dataclass
 class SplitNode:
     """A horizontal or vertical split with N children.

     direction:
         "h" — children laid out left-to-right (vertical dividers).
         "v" — children laid out top-to-bottom (horizontal dividers).
     weights: positive floats; effective share = w_i / sum(weights).
     """

     direction: str
     children: list
     weights: list[float]

     def normalized_weights(self) -> list[float]:
         s = sum(self.weights) or 1.0
         return [w / s for w in self.weights]


 LayoutNode = Union[LeafNode, SplitNode]


