 def background_color_from_settings(settings) -> QColor:
     color = getattr(settings, "export_background_color", None)
     if color is None:
         return QColor(20, 20, 20)
     if isinstance(color, QColor):
         return QColor(color)
     channels = (
         getattr(color, "r", 20),
         getattr(color, "g", 20),
         getattr(color, "b", 20),
         getattr(color, "a", 255),
     )
     return QColor(*channels)


