         self.label.setObjectName("ValuePopupLabel")
         self.label.setAlignment(Qt.AlignmentFlag.AlignCenter)
         self.label.setContentsMargins(scaled_px(4), scaled_px(4), scaled_px(4), scaled_px(4))
