     def _apply_label_typography(self) -> None:
         apply_ui_font(self.label, pixel_size=13, bold=True)
         apply_text_color(
             self.label, ThemeManager.get_instance().get_color("dialog.text")
         )

     def set_content(
         self,
         *,
         text: str = "",
         pixmap: QPixmap | None = None,
         size: QSize | None = None,
     ) -> None:
