             try:
                 timer.stop()
             except RuntimeError:
                 self._popup_timers.pop(key, None)
         if popup is None:
             self._forget_popup(key)
             return
         try:
             popup.parentWidget()
         except RuntimeError:
             self._forget_popup(key)

