# re-apply the i18n migrations: tab-only keys to tab json + settings keys restore + ui_scale
import json, glob, subprocess, sys, re
LANGS = ("en", "ru", "pt_BR", "zh")
def git_show(path):
    return subprocess.run(["git","show",f"HEAD:{path}"],capture_output=True,text=True,check=True).stdout
def head_shared(lang):
    keys = {}
    for p in glob.glob(f"src/resources/i18n/{lang}/*/*.json"):
        try: d = json.loads(git_show(p))
        except Exception: continue
        def walk(o, prefix=""):
            if isinstance(o, dict):
                for k, v in o.items():
                    if isinstance(v, dict): walk(v, f"{prefix}.{k}" if prefix else k)
                    else: keys[f"{prefix}.{k}" if prefix else k] = v
        walk(d)
    return keys
def refs_of(key):
    files = set()
    for path in glob.glob("src/**/*.py", recursive=True):
        if "__pycache__" in path: continue
        try: s = open(path, encoding="utf-8").read()
        except Exception: continue
        if f'"{key}"' in s or f"'{key}'" in s: files.add(path)
    return files
branch_keys = {k for k in head_shared("en") if (lambda f: bool(f) and all("src/tabs/image_compare/" in x for x in f))(refs_of(k))}
for lang in LANGS:
    shared_vals = head_shared(lang)
    tab_p = f"src/tabs/image_compare/resources/i18n/{lang}/image_compare.json"
    tab = json.load(open(tab_p, encoding="utf-8"))
    ic = tab.setdefault("image_compare", {})
    for key in sorted(branch_keys):
        if key not in shared_vals: continue
        parts = key.split(".")
        node = ic
        for part in parts[:-1]: node = node.setdefault(part, {})
        if isinstance(node, dict): node[parts[-1]] = shared_vals[key]
    with open(tab_p, "w", encoding="utf-8") as f:
        json.dump(tab, f, ensure_ascii=False, indent=2); f.write("\n")
    for p in glob.glob(f"src/resources/i18n/{lang}/*/*.json"):
        try: d = json.load(open(p, encoding="utf-8"))
        except Exception: continue
        changed = [False]
        def rm(obj, prefix=""):
            if isinstance(obj, dict):
                for k in list(obj):
                    full = f"{prefix}.{k}" if prefix else k
                    if full in branch_keys:
                        del obj[k]; changed[0] = True
                    else: rm(obj[k], full)
        rm(d)
        if changed[0]:
            with open(p, "w", encoding="utf-8") as f:
                json.dump(d, f, ensure_ascii=False, indent=2); f.write("\n")
print("tab migration done; branch keys:", len(branch_keys))
EOF

